import { useEffect, useState } from 'react';
import {useLocation, useNavigate} from 'react-router-dom';
import { useAuth } from "../context/AuthContext";
import {processUserData} from "../utils/apiUtils";
import "../screens/UserAuth/AuthScreens.scss";

async function fetchUserProfile(accessToken) {
    const endpoint = `${process.env.REACT_APP_API_URL}/api/users/profile`;
    const headers = { "Authorization": `Bearer ${accessToken}` };
    const response = await fetch(endpoint, { headers });
    return await response.json();
}
export default function LoginCallback() {
    const { login } = useAuth();
    const [token, setToken] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const location = useLocation();
    const navigate = useNavigate();

    useEffect(() => {
        const queryParams = new URLSearchParams(location.search);
        const extractedToken = queryParams.get('token');
        if (extractedToken) {
            setToken(extractedToken);
        }
    }, [location]);

    useEffect(() => {
        if (token) {
            const returnUrl = sessionStorage.getItem('returnUrl') || '/';
            sessionStorage.removeItem('returnUrl');
            async function getUserProfile() {
                try {
                    const data = await fetchUserProfile(token);
                    await login(processUserData(data));
                    navigate(returnUrl);
                } catch (error) {
                    console.error('Error fetching user profile:', error);
                    setErrorMessage('We could not complete your login. Please try again.');
                }
            }
            getUserProfile();
        }
    }, [token, navigate, login]);
    if (errorMessage) {
        return (
            <div className="auth-loader">
                <div>
                    <h2>Login failed</h2>
                    <p>{errorMessage}</p>
                </div>
            </div>
        );
    }
    return (
        <div className="auth-loader">
            <div>
                <h2>Processing login...</h2>
                <p>Please wait while we finish signing you in.</p>
            </div>
        </div>
    );
}

